import json, sys
d = json.load(sys.stdin)
rows = d['rows']
depts = ['Engineering', 'Sales', 'Marketing', 'Support']
errors = []
for r in rows:
    i = r['id']
    expected_name = f'Employee {i:02d}'
    expected_dept = depts[(i-1) % 4]
    expected_salary = 50000 + ((i * 37) % 100) * 100
    expected_active = i % 5 != 0
    if r['name'] != expected_name:
        errors.append(f'id={i} name: expected {expected_name}, got {r[\"name\"]}')
    if r['department'] != expected_dept:
        errors.append(f'id={i} dept: expected {expected_dept}, got {r[\"department\"]}')
    if r['salary'] != expected_salary:
        errors.append(f'id={i} salary: expected {expected_salary}, got {r[\"salary\"]}')
    if r['active'] != expected_active:
        errors.append(f'id={i} active: expected {expected_active}, got {r[\"active\"]}')
if errors:
    print('ERRORS:')
    for e in errors: print(' ', e)
